python3 -I -c "import json; from pathlib import Path; defwalk=None; exec('def walk(x, case, artifact):
 if isinstance(x, dict):
  case=x.get("case_id",case); artifact=x.get("artifact_path",artifact)
  if any("native" in str(v).lower() for k,v in x.items() if not isinstance(v,(dict,list))):
   print(json.dumps({"case_id":case,"slot_id":x.get("slot_id",x.get("id")),"artifact_path":artifact}))
  for v in x.values(): walk(v,case,artifact)
 elif isinstance(x,list):
  for v in x: walk(v,case,artifact)'); [(walk(json.loads(p.read_text()),p.stem,None)) for p in sorted(Path('benchmark/cases/dev').glob('*.json'))]"

